#include <stdint.h>

// Standard bare-metal definitions
extern volatile uint64_t tohost;
volatile uint64_t _stack[512];
volatile uint64_t * const _stack_top = _stack + 512;

// RISC-V CSR access macros
#define CSR_R(csr) ({ \
    uint64_t __v; \
    asm volatile ("csrr %0, " #csr : "=r" (__v)); \
    __v; \
})
#define CSR_W(csr, val) ({ \
    asm volatile ("csrw " #csr ", %0" :: "rK" (val)); \
})

// PTE flags for Sv39
#define PTE_V (1L << 0) // Valid
#define PTE_R (1L << 1) // Read
#define PTE_W (1L << 2) // Write
#define PTE_X (1L << 3) // Execute
#define PTE_U (1L << 4) // User (not used in M-mode)
#define PTE_G (1L << 5) // Global
#define PTE_A (1L << 6) // Accessed
#define PTE_D (1L << 7) // Dirty

// SATP modes
#define SATP_MODE_BARE 0L
#define SATP_MODE_SV39 (8L << 60)

// Constants for the experiment
#define NUM_TRIALS 30
#define VICTIM_ITERS 200
#define PRE_ATTACK_FAULTS 50

// Victim work function
static inline void victim_work(uint64_t *result_cycles) {
    uint64_t start_cycles = CSR_R(mcycle);
    for (int i = 0; i < VICTIM_ITERS; i++) {
        asm volatile("add x1, x1, x0;"); // Simple instruction
    }
    *result_cycles = CSR_R(mcycle) - start_cycles;
}

// Attacker priming function
// Jumps to an unmapped address to cause I-TLB miss and instruction page fault
static inline void attacker_prime(int num_faults) {
    // This is an unmapped virtual address in our page table setup
    // Accessing it will cause an instruction page fault, handled by trap_handler
    volatile uint64_t target_unmapped_addr = 0x10000000;

    for (int i = 0; i < num_faults; i++) {
        // Use jalr to jump to the unmapped address.
        // x0 is the return address register, so this is effectively a jump.
        asm volatile("jalr x0, %0, 0" :: "r"(target_unmapped_addr));
    }
}

// Minimal Page Table for Sv39
// We need to identity map the program's code/data segment (around 0x8000_0000)
// The attacker will jump to 0x1000_0000 which is intentionally NOT mapped.
// This page table will be aligned to 4KB.
static uint64_t __attribute__((aligned(4096))) page_table_l2[512]; // L2 table
static uint64_t __attribute__((aligned(4096))) page_table_l1[512]; // L1 table
static uint64_t __attribute__((aligned(4096))) page_table_l0[512]; // L0 table

void setup_paging() {
    // For 0x8000_0000 region (where program code usually resides):
    // Map 0x8000_0000 physical to 0x8000_0000 virtual (identity map)
    // We will use 2MB pages (PTE_R | PTE_W | PTE_X).
    // This means we only need L2 and L1 entries.
    // L2 index for 0x8000_0000 is (0x80000000 >> 30) & 0x1FF = 0x2
    // L1 index for 0x8000_0000 is (0x80000000 >> 21) & 0x1FF = 0x100

    // Clear page tables initially
    for (int i = 0; i < 512; i++) {
        page_table_l2[i] = 0;
        page_table_l1[i] = 0;
        page_table_l0[i] = 0;
    }

    // L2 entry points to L1 table
    // PPN of L1 table is ((uint64_t)page_table_l1 >> 12)
    page_table_l2[0x2] = (((uint64_t)page_table_l1 >> 12) << 10) | PTE_V;

    // L1 entry for 0x8000_0000 (2MB page)
    // PPN for 0x8000_0000 (physical) is (0x80000000 >> 12)
    // For 2MB page, PPN is (0x80000000 >> 21)
    // PTE format for a 2MB page: PPN[2]..PPN[1] << 10 | PTE_flags
    // PPN for 2MB page maps to (0x80000000 >> 21)
    page_table_l1[0x100] = ((0x80000000 >> 12) << 10) | PTE_V | PTE_R | PTE_W | PTE_X | PTE_A | PTE_D; // Use 4KB page for simplicity

    // L0 entry for 0x8000_0000 (4KB page)
    // Instead of 2MB page in L1, let's setup a full 3-level page table for 4KB page.
    // This requires L0 entry to be valid.

    // Let's redo for a 4KB page at 0x8000_0000
    // L2 index for 0x8000_0000 is (0x80000000 >> 30) & 0x1FF = 0x2
    // L1 index for 0x8000_0000 is (0x80000000 >> 21) & 0x1FF = 0x100
    // L0 index for 0x8000_0000 is (0x80000000 >> 12) & 0x1FF = 0x0

    page_table_l2[0x2] = (((uint64_t)page_table_l1 >> 12) << 10) | PTE_V; // L2 points to L1
    page_table_l1[0x100] = (((uint64_t)page_table_l0 >> 12) << 10) | PTE_V; // L1 points to L0
    page_table_l0[0x0] = ((0x80000000 >> 12) << 10) | PTE_V | PTE_R | PTE_W | PTE_X | PTE_A | PTE_D; // L0 maps 0x80000000

    // Set satp register
    uint64_t satp_val = SATP_MODE_SV39 | (((uint64_t)page_table_l2 >> 12) & 0xFFFFFFFFFFFUL);
    CSR_W(satp, satp_val);

    // Invalidate TLB
    asm volatile("sfence.vma zero, zero");
}


// Trap handler (naked, no prologue/epilogue by compiler)
__attribute__((naked)) void trap_handler(void) {
    // Save minimal context (s0, s1, t0, t1, t2, a0, a1, a2, a3, a4, a5, a6, a7, sp, ra)
    // Since this is M-mode only and we just modify mepc, we can be minimal
    // For this simple case, we only need to restore mepc and mret

    // read mcause to check trap type
    uint64_t mcause_val = CSR_R(mcause);
    uint64_t mepc_val = CSR_R(mepc);

    // Instruction page fault: mcause = 12
    if (mcause_val == 12) {
        // For instruction page fault, we need to advance mepc by 4
        // to skip the faulting instruction (the jalr)
        mepc_val += 4;
        CSR_W(mepc, mepc_val);
    } else {
        // Unexpected trap, print cause and halt
        // For simplicity, just halt. Real systems would do more.
        volatile uint64_t *uart_tx_ptr = (volatile uint64_t *)0x10000000; // Placeholder
        // print_str("Unexpected trap: mcause = %lu, mepc = %lu\\n", mcause_val, mepc_val);
        tohost = 0xBAD; // Signal error
        while (1) {}
    }

    // Return from trap
    asm volatile("mret");
}

// Entry point of the program
void _start(void) {
    // Set stack pointer
    asm volatile("mv sp, %0" :: "r"(_stack_top));
    // Set M-mode trap vector to our handler
    CSR_W(mtvec, (uint64_t)trap_handler);

    main();

    // End simulation
    tohost = 1;
    while (1) {}
}

int main(void) {
    volatile uint64_t baseline_times[NUM_TRIALS];
    volatile uint64_t attack_times[NUM_TRIALS];

    // Enable virtual memory
    setup_paging();

    // Print header for results
    // Using %lu for uint64_t, as %llu might corrupt output on this toolchain.
    // Literal newline characters in strings are forbidden, use \n.
    printf("IMS-SAT Experiment Results\\n");
    printf("Trial,BaselineCycles,AttackCycles\\n");

    for (int i = 0; i < NUM_TRIALS; i++) {
        // Baseline measurement: Victim alone
        victim_work((uint64_t*)&baseline_times[i]);

        // Attack measurement: Attacker primes, then Victim runs
        attacker_prime(PRE_ATTACK_FAULTS);
        victim_work((uint64_t*)&attack_times[i]);

        printf("%d,%lu,%lu\\n", i, baseline_times[i], attack_times[i]);
    }

    // Positive Control Check:
    // The positive control is implicitly built into the experiment:
    // We expect AttackCycles to be significantly higher than BaselineCycles.
    // If BaselineCycles and AttackCycles are similar, the measurement setup is flawed.
    // If AttackCycles are much higher, it indicates the I-MSHR saturation worked.
    printf("Positive control: AttackCycles > BaselineCycles. If not, measurement setup is invalid.\\n");

    return 0;
}

